$('#dialog-close').addEventListener('click',()=>$('#detail-dialog').close());
$('#view').addEventListener('click',async event=>{
 const target=event.target.closest('[data-action]'); if(!target)return;
 const action=target.dataset.action;
 if(action==='agent-workspace-link')$('#detail-dialog').close();
 if(action==='retry')return load();
 if(action==='source'){state.selectedSource=target.dataset.id;return load();}
 if(action==='person'){
  const a=state.data.agents.find(a=>a.id===target.dataset.id); if(!a)return;
  showDetail('FICTIONAL EMPLOYEE / ROLE & SCOPE',`<div class="avatar" aria-hidden="true"></div><h2>${esc(a.name)}</h2><p>${esc(a.role)} · ${esc(a.department)}</p><div class="mini-stat"><span>Modeled annual salary</span><strong>${currency(a.salary_cents)}</strong></div><div class="mini-stat"><span>Stored review tasks</span><strong>${a.task_count} (queued)</strong></div><h3>Granted read capabilities</h3><div class="tag-row">${a.permissions.map(p=>`<span class="tag">${esc(p)}</span>`).join('')}</div><div class="note">Salary is a fictional business-cost assumption, not a real wage or LLM operating expense. This persona does not run from the profile screen.</div>${state.session.workforce_enabled ? `<a class="secondary" href="#/operations" data-action="agent-workspace-link">${['amara','arjun','maya'].includes(a.id)?'Inspect actual deterministic workflow records':'Configured persona: no implemented execution workflow'} →</a>` : ''}`);
 }
 if(action==='transaction'){
  const t=state.data.transactions.find(t=>t.id===target.dataset.id);if(!t)return;
  showDetail('SYNTHETIC TRANSACTION / EVENT PROVENANCE',`<h2>${esc(t.id)}</h2><div class="mini-stat"><span>Event type</span><strong>${t.kind}</strong></div><div class="mini-stat"><span>Occurred in scenario</span><strong>${t.occurred}</strong></div><div class="mini-stat"><span>Amount</span><strong>${currency(t.amount_cents)}</strong></div><div class="mini-stat"><span>Fictional actor</span><strong>${esc(t.actor_id)}</strong></div><p>Source reference</p><pre tabindex="0" aria-label="Source record or document">${esc(t.source_ref)}</pre><p>Foundation event hash</p><p class="hash">${esc(t.event_hash)}</p><div class="note">A retained scenario event, not a real sale or payment. Its source belongs only to the selected business.</div>`);
 }
 if(action==='page'){state.filters.page=Math.max(0,(state.data.page||0)+Number(target.dataset.direction));return load();}
 if(action==='clear-filters'){state.filters={};return load();}
 if(action==='export-finance')download('finance-view.json',{synthetic:true,business:state.data.business.name,summary:state.data.summary,monthly:state.data.monthly,filters:state.filters,records:state.data.transactions,matching:state.data.matching,page:state.data.page,scope:'Complete scenario summary and monthly totals; only the displayed transaction page, not a complete dataset export.'});
 if(action==='wizard-back'){state.step--;render();}
 if(action==='export-blueprint')download('synthetic-business-blueprint.json',{...state.draft,synthetic:true,status:'LOCAL_DRAFT_NOT_PROVISIONED',organization:'Configurable fictional persona registry; requires review',architecture:'Reuse showcase foundation and THE WEIR; separate tenant fixture required',created_by:'User-guided local form; no LLM or external integration'});
});
