// Phase 4: real tool execution records, explicitly deterministic; never fabricated activity.
const wf={catalog:null,current:null,busy:false,error:'',request:null,tenant:null};
async function wfFetch(path,body){
 const res=await fetch(path,{credentials:'same-origin',method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-Nasha-Request':'1','X-CSRF-Token':state.session.csrf}:{},body:body?JSON.stringify(body):undefined});
 const data=await res.json();if(!res.ok)throw new Error(data.error || 'Workflow request refused');return data;
}
async function workflowCatalog(){
 const tenant=state.session.selected, sessionKey=state.session.csrf;
 try{
  const data=await wfFetch('/api/workflows');
  if(state.route!=='operations'||state.session?.selected!==tenant||state.session?.csrf!==sessionKey)return;
  if(wf.tenant!==tenant){wf.current=null;wf.request=null;wf.error='';}
  wf.tenant=tenant;wf.catalog=data;drawWorkflow();
 }catch(error){if($('#workflow-area'))$('#workflow-area').innerHTML=`<p role="alert">${esc(error.message)}</p>`;}
}
function drawWorkflow(){
 const area=$('#workflow-area');if(!area||wf.tenant!==state.session.selected)return;
 const current=wf.current,run=current?.workflow;
 const completed=current?.events.filter(e=>e.kind==='agent_completed') || [];
 const failures=current?.events.filter(e=>e.kind==='failure') || [];
 const status={AWAITING_APPROVAL:'Pending human approval',EXECUTED:'Approved simulated execution',REJECTED:'Rejected execution',FAILED:'Failed execution',BLOCKED:'Blocked by finance',ABSTAINED:'No replenishment required',APPROVED:'Approved; execution not confirmed'};
 area.innerHTML=`<div class="panel-title"><div><span class="eyebrow">GOVERNED WORKFORCE / PHASE 4</span><h2>Inventory discrepancy → procurement decision</h2></div><span class="tag">DETERMINISTIC REPLAY</span></div><p>Actual structured tool calls through the existing platform and THE WEIR. No live LLM inference, real purchase, inventory update, or historical journal mutation.</p><form id="workflow-start" class="filters workflow-controls"><label>Synthetic scenario<select name="scenario" id="workflow-scenario">${wf.catalog.scenarios.map(s=>`<option value="${s.id}" ${wf.request?.scenario===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select></label><button class="primary" type="submit" ${wf.busy?'disabled':''}>${wf.busy?'Processing bounded request…':'Start authorized workflow'}</button><label>Recorded workflows<select id="workflow-history"><option value="">Select an existing run</option>${wf.catalog.runs.map(r=>`<option value="${r.id}" ${run?.corr_id===r.id?'selected':''}>${esc(r.id)} / ${esc(r.state)}</option>`).join('')}</select></label></form>${wf.error?`<div class="note warning" role="alert">${esc(wf.error)}. No success is assumed; inspect recorded state before retrying.</div>`:''}${wf.busy?'<p role="status">Request in progress. Steps appear only after actual execution records exist; no animated activity is fabricated.</p>':''}${current?`<div class="workflow-status"><strong>${status[run.state]||esc(run.state)}</strong><span class="hash">${esc(run.corr_id)} · ${esc(current.tenant)}</span><button class="secondary" data-wf="refresh" ${wf.busy?'disabled':''}>Refresh recorded state</button></div><div class="workflow-agents">${wf.catalog.agents.map(a=>{const record=completed.find(e=>e.agent===a.id);const started=current.events.some(e=>e.kind==='agent_started'&&e.agent===a.id);return `<button class="workflow-agent" data-wf="agent" data-agent="${a.id}"><span class="eyebrow">${esc(a.role)}</span><strong>${esc(state.data.tasks.find(t=>t.agent_id===a.id)?.agent_name||a.id)}</strong><span>${record?'Recorded deterministic result':started?'Stopped; inspect error records':'Not executed in this run'}</span><small>${esc(a.tool)}</small></button>`;}).join('')}</div><div class="workflow-finance"><div class="mini-stat"><span>Proposed hypothetical purchase</span><strong>${current.action?currency(current.action.amount_cents):'No proposal'}</strong></div><div class="mini-stat"><span>Scenario budget assumption</span><strong>${currency(current.context.scenario.budget_cents)}</strong></div><div class="mini-stat"><span>Available modeled cash / foundation</span><strong>${currency(current.context.cash_cents)}</strong></div><div class="mini-stat"><span>Finance recommendation</span><strong>${esc(completed.find(e=>e.agent==='maya')?.output.recommendation||'Not evaluated')}</strong></div></div><div class="note">Inventory counts, target stock, unit costs and budget are explicitly injected scenario assumptions. Available cash comes from the existing selected-business fixture. Approval permits only a separate simulated DRAFT_NOT_SENT record.</div>${current.approval?`<div class="workflow-approval"><div><span class="eyebrow">EXACT-ACTION HUMAN REVIEW</span><h3>${run.state==='AWAITING_APPROVAL'?'Execution is blocked pending approval.':status[run.state]||esc(run.state)}</h3><p>Approval ${esc(current.approval.id)} · ${esc(current.approval.state)}<br>Expires ${esc(new Date(current.approval.expires*1000).toLocaleString())}</p><p class="hash">Action SHA-256: ${esc(current.action_hash)}</p></div><div class="workflow-review-actions"><button class="secondary" data-wf="reject" ${wf.busy||run.state!=='AWAITING_APPROVAL'?'disabled':''}>Reject proposed action</button><button class="primary" data-wf="approve" ${wf.busy||run.state!=='AWAITING_APPROVAL'?'disabled':''}>Approve simulated draft</button></div></div>`:''}${failures.map(e=>`<div class="note warning">Recorded error: ${esc(e.error)}. ${esc(e.detail||'No external action was performed.')}</div>`).join('')}${current.drafts.length?`<div class="note"><strong>Simulated action recorded</strong><br>${current.drafts.map(d=>`${esc(d.id)} / ${esc(d.state)}`).join('<br>')}<br>Supplier transmission: none. Historical financial fixtures: unchanged.</div>`:''}<details><summary>Inspect workflow audit, tool calls and policy decisions (${current.events.length} recorded events)</summary><p class="hash">Ledger + THE WEIR chain status: ${current.audit_valid?'verified':'FAILED / do not execute'}</p><div class="workflow-events">${current.events.map(e=>`<details><summary>${e.seq}. ${esc(e.kind)} · ${esc(e.actor||'system')}</summary><pre tabindex="0" aria-label="Recorded workflow event">${esc(JSON.stringify(e,null,2))}</pre></details>`).join('')}</div></details>`:'<div class="empty-state"><h3>No workflow selected.</h3><p>Launch a synthetic scenario to inspect Operations, Procurement and Finance tool executions. The other configured personas remain inactive.</p></div>'}`;
}
async function wfLoadRun(id){
 const tenant=state.session.selected,sessionKey=state.session.csrf;const data=await wfFetch('/api/workflows?run='+encodeURIComponent(id));
 if(state.route==='operations'&&state.session?.selected===tenant&&state.session?.csrf===sessionKey&&data.tenant===tenant){wf.current=data;wf.tenant=tenant;}
}
async function wfCommand(command){
 if(wf.busy)return;
 const tenant=state.session.selected,sessionKey=state.session.csrf;const selected=$('#workflow-scenario')?.value;
 wf.busy=true;wf.error='';$('#business-select').disabled=true;drawWorkflow();
 try{
  if(command==='start'){
   if(!wf.request||wf.request.scenario!==selected)wf.request={scenario:selected,idempotency_key:crypto.randomUUID()};
   const result=await wfFetch('/api/workflows/start',wf.request);
   if(state.session?.selected===tenant&&state.session?.csrf===sessionKey){wf.current=result;wf.request=null;}
  }else if(command==='refresh')await wfLoadRun(wf.current.workflow.corr_id);
  else{
   const c=wf.current;
   const result=await wfFetch('/api/workflows/review',{run:c.workflow.corr_id,approval_id:c.approval.id,action_hash:c.action_hash,decision:command});
   if(state.session?.selected===tenant&&state.session?.csrf===sessionKey)wf.current=result;
  }
 }catch(error){
  wf.error=error.message;
  if(wf.current){try{await wfLoadRun(wf.current.workflow.corr_id);}catch{}}
 }finally{
  wf.busy=false;$('#business-select').disabled=false;
  if(state.session?.selected===tenant&&state.session?.csrf===sessionKey&&state.route==='operations'){
   try{wf.catalog=await wfFetch('/api/workflows');}catch{}
   drawWorkflow();announce(wf.error||'Workflow recorded: '+(wf.current?.workflow.state||'no state'));
  }
 }
}
$('#view').addEventListener('submit',event=>{if(event.target.id==='workflow-start'){event.preventDefault();wfCommand('start');}});
$('#view').addEventListener('change',event=>{
 if(event.target.id==='workflow-history'&&event.target.value)wfLoadRun(event.target.value).then(drawWorkflow).catch(e=>{wf.error=e.message;drawWorkflow();});
 if(event.target.id==='workflow-scenario')wf.request=null;
});
$('#view').addEventListener('click',event=>{
 const control=event.target.closest('[data-wf]');if(!control)return;
 if(control.dataset.wf==='agent'){
  const agent=control.dataset.agent;
  const completed=wf.current.events.filter(e=>e.agent===agent||e.actor===agent);
  showDetail('ACTUAL AGENT WORKSPACE / DETERMINISTIC EXECUTION',`<h2>${esc(wf.catalog.agents.find(a=>a.id===agent).role)}</h2><p>Workflow ${esc(wf.current.workflow.corr_id)} · ${esc(wf.current.workflow.state)}. This is deterministic tool execution, not live AI inference. Inspect inputs, outputs, timing, retry events, and failures below.</p><pre tabindex="0" aria-label="Actual agent execution records">${esc(JSON.stringify(completed,null,2))}</pre><p>No per-agent model reliability score is claimed. Mounted deterministic-control evaluation reports:</p>${(wf.catalog.evaluation||[]).map(r=>`<div class="mini-stat"><span>${esc(r.label)}</span><strong>${r.available?`${r.tests-r.failures-r.skipped} passed / ${r.failures} failed / ${r.skipped} skipped`:`Unavailable / no result claimed`}</strong></div>`).join('')||'<p>No evaluation report is mounted. See the retained local test results.</p>'}`);
 }else wfCommand(control.dataset.wf);
});

try { enter(await api('/api/session')); } catch(e) { if(e.name!=='AbortError' && e.status!==401)$('#login-error').textContent='The local review host is unavailable.'; }
